'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const orders=[['and','or','not'],['and','not','or'],['or','and','not'],['or','not','and'],['not','and','or'],['not','or','and']];
let variant=OrionProgress.variant('logic'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,a=false,b=false,solved=false,hintDepth=0,records={},last=null,state='ready',saveFailed=false;
function rule(){return orders[variant][stage];}
function outcome(kind,x,y){return kind==='and'?x&&y:kind==='or'?x||y:!x;}
function combinations(){return rule()==='not'?['0','1']:['00','01','10','11'];}
function key(){return Number(a)+(rule()==='not'?'':String(Number(b)));}
function ready(){return combinations().every(k=>Object.hasOwn(records,k));}
function resetTrial(){a=b=false;solved=false;hintDepth=0;records={};last=null;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('logic')){variant=v;stage=0;resetTrial();}
function toggle(i){if(solved||(i!==0&&i!==1)||(i===1&&rule()==='not'))return;if(i===0)a=!a;else b=!b;last=null;state='changed';render();}
function test(){if(solved)return;last=outcome(rule(),a,b);records[key()]=last;state='tested';render();}
function choose(kind){if(solved||!ready()||!['and','or','not'].includes(kind))return;if(kind!==rule()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('truth');render();if(stage<2)$('next').focus();}
function offering(k){return t(`A ${k[0]==='1'?'in':'out'}${k.length===2?` · B ${k[1]==='1'?'in':'out'}`:''}`,`A ${k[0]==='1'?'放入':'取走'}${k.length===2?` · B ${k[1]==='1'?'放入':'取走'}`:''}`);}
function ruleName(k){return k==='and'?t('AND · Both gems are present','AND 且 · 兩顆寶石都在'):k==='or'?t('OR · At least one gem is present','OR 或 · 至少有一顆寶石'):t('NOT A · Gem A is absent','NOT A 非 · 沒有寶石 A');}
function hints(){const missing=combinations().find(k=>!Object.hasOwn(records,k));return[t('Compare one offering that opens the bridge with one that keeps it closed. What changed?','比較開橋和關橋的供奉，哪裡不同？'),rule()==='not'?t('This owl watches only gem A. Try with A and without A.','這隻貓頭鷹只看寶石 A。試試放入和取走 A。'):t('Try neither gem, only A, only B, and both. Does “both” behave like “just one”?','試試沒有寶石、只有 A、只有 B，以及兩顆都有。「兩顆都有」和「只有一顆」的結果一樣嗎？'),missing?t('Next untested offering: ','下一個未測試的供奉：')+offering(missing):t('The rule that matches every row is: ','符合每一行的規則是：')+ruleName(rule())];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Bridge of Truth · Orion','石像的真假橋 · Orion');$('stageTitle').textContent=t(`Owl ${stage+1} · Secret set ${variant+1}`,`第 ${stage+1} 隻貓頭鷹 · 秘密組 ${variant+1}`);$('sceneStatus').textContent=complete?t('The treasury path is open.','通往寶庫的路打開了。'):t(`Rules discovered · ${count} / 3`,`已發現 ${count} / 3 個規則`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('progressCount').textContent=$('sceneStatus').textContent;$('progressBar').value=count;$('scene').classList.toggle('complete',complete);
 $('inputNote').textContent=rule()==='not'?t('This owl has one gem socket: A.','這隻石像只有一個寶石槽：A。'):t('This owl has two gem sockets: A and B. Try every offering.','這隻石像有兩個寶石槽：A 和 B。試試每種供奉。');
 for(const [i,on] of [a,b].entries()){const el=$(i?'gemB':'gemA');el.hidden=i===1&&rule()==='not';el.disabled=solved;el.setAttribute('aria-pressed',String(on));el.innerHTML=`<span class="gem-icon" aria-hidden="true">${i?'◆':'◈'}</span>${i?'B':'A'} · ${on?t('In the socket','已放入'):t('In your bag','在袋中')}`;el.setAttribute('aria-label',t(`Gem ${i?'B':'A'}: ${on?'in the socket, tap to remove':'in your bag, tap to add'}`,`寶石 ${i?'B':'A'}：${on?'已放入，點按取走':'在袋中，點按放入'}`));}
 $('model').classList.toggle('pass',last===true);$('model').classList.toggle('wait',last===null);$('bridgeState').textContent=last===null?t('Awaiting a test','等待測試'):last?t('OPEN · crossing allowed','開啟 · 可以通過'):t('CLOSED · try another offering','關閉 · 試試其他供奉');
 const msg={ready:t('Start with any offering—even no gems. Tap Test to see what happens.','任何供奉都可以開始，沒有寶石也可以。按「試試」觀察結果。'),changed:t('Offering changed. Tap Test to ask the owl.','供奉已改變。按「試試」詢問石像。'),tested:ready()?t('All combinations tested! Choose the rule that fits every result.','所有組合都測試了！選出符合全部結果的規則。'):t('Evidence recorded. Try a combination marked “?”.','證據已記錄。試試標有「？」的組合。'),wrong:t('That rule does not fit every result. Compare the rows and choose again.','這個規則不符合所有結果。比較各行，再選一次。'),success:t('Rule discovered! The owl releases a seal.','發現規則！石像解開了一道封印。')};$('feedback').textContent=msg[state];$('evidenceTitle').textContent=t(`Your evidence · ${Object.keys(records).length}/${combinations().length}`,`你的證據 · ${Object.keys(records).length}/${combinations().length}`);$('log').innerHTML=combinations().map(k=>`<div class="trial-row"><span>${offering(k)}</span><span>${Object.hasOwn(records,k)?records[k]?t('OPEN','開啟'):t('CLOSED','關閉'):'?'}</span></div>`).join('');
 $('ruleChoices').hidden=!ready()||solved;for(const k of ['and','or','not'])$(k).textContent=ruleName(k);$('test').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Please try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('truth')?t('Truth Sigil saved in your collection.','真理符印已存入收藏。'):'';
}
$('gemA').onclick=()=>toggle(0);$('gemB').onclick=()=>toggle(1);$('test').onclick=test;$('retry').onclick=()=>{if(!solved)resetTrial();};for(const k of ['and','or','not'])$(k).onclick=()=>choose(k);$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('gemA').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('logic',variant);observedVariant=OrionProgress.variant('logic');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('truth');render();};
function syncProgress(){const v=OrionProgress.variant('logic'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('truth')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
